<script setup>
import { ref,computed } from 'vue'
import { ArrowLeft,Building2,Users,CalendarDays } from 'lucide-vue-next'
import { useRouter,useRoute } from 'vue-router'
import { loadData } from '../services/storage'
const router=useRouter(),route=useRoute(),query=ref(String(route.query.q||''))
const organizations=loadData('organizations'),members=loadData('members'),events=loadData('events')
const match=(s)=>String(s||'').toLowerCase().includes(query.value.trim().toLowerCase())
const orgResults=computed(()=>query.value.trim()?organizations.filter(o=>match(o.name+' '+o.description+' '+o.president)):[])
const memberResults=computed(()=>query.value.trim()?members.filter(m=>match(m.name+' '+m.course+' '+m.position+' '+m.organization)):[])
const eventResults=computed(()=>query.value.trim()?events.filter(e=>match(e.title+' '+e.organization+' '+e.location+' '+e.description)):[])
</script>
<template><div class="page"><button class="back-button" @click="router.back()"><ArrowLeft :size="18"/> Back</button><section class="page-intro"><div><span class="eyebrow">FIND SOMETHING</span><h1>Search</h1><p>Search organizations, members, and events.</p></div></section><form class="search-bar search-page-bar" @submit.prevent="router.replace({path:'/search',query:{q:query}})"><input v-model="query" placeholder="Search anything in OrgConnect..."/><button class="btn btn-primary">Search</button></form><section class="detail-section"><div class="section-heading"><h2><Building2 :size="19"/> Organizations ({{orgResults.length}})</h2></div><button v-for="o in orgResults" :key="o.id" class="simple-row clickable" @click="router.push(`/organizations/${o.id}`)"><div class="org-avatar small">{{o.initials}}</div><div><strong>{{o.name}}</strong><span>{{o.description}}</span></div></button><p v-if="query && !orgResults.length" class="muted">No matching organizations.</p></section><section class="detail-section"><div class="section-heading"><h2><Users :size="19"/> Members ({{memberResults.length}})</h2></div><button v-for="m in memberResults" :key="m.id" class="simple-row clickable" @click="router.push(`/members/${m.id}`)"><div class="avatar avatar-member">{{m.name.split(' ').map(x=>x[0]).slice(0,2).join('')}}</div><div><strong>{{m.name}}</strong><span>{{m.position}} · {{m.organization}}</span></div></button><p v-if="query && !memberResults.length" class="muted">No matching members.</p></section><section class="detail-section"><div class="section-heading"><h2><CalendarDays :size="19"/> Events ({{eventResults.length}})</h2></div><button v-for="e in eventResults" :key="e.id" class="simple-row clickable" @click="router.push('/events')"><div class="row-icon"><CalendarDays/></div><div><strong>{{e.title}}</strong><span>{{e.date}} · {{e.location}}</span></div></button><p v-if="query && !eventResults.length" class="muted">No matching events.</p></section></div></template>
